#include "stdlib/stats/strided/dmadsorted.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/stats/strided/dmediansorted.h" // For median calculation
#include <stdlib.h> // For qsort
#include <math.h>   // For fabs

// Comparison function for qsort
static int compare_doubles( const void *a, const void *b ) {
	double arg1 = *(const double*)a;
	double arg2 = *(const double*)b;
	if (arg1 < arg2) return -1;
	if (arg1 > arg2) return 1;
	return 0;
}

/**
* Computes the median absolute deviation of a sorted double-precision floating-point strided array.
*
* @param N        number of indexed elements
* @param X        sorted input array
* @param strideX  stride length
* @return         output value (median absolute deviation)
*/
double API_SUFFIX(stdlib_strided_dmadsorted)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	return API_SUFFIX(stdlib_strided_dmadsorted_ndarray)( N, X, strideX, ox );
}

/**
* Computes the median absolute deviation of a sorted double-precision floating-point strided array using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        sorted input array
* @param strideX  stride length
* @param offsetX  starting index for X
* @return         output value (median absolute deviation)
*/
double API_SUFFIX(stdlib_strided_dmadsorted_ndarray)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	double median;
	double *diffs;
	CBLAS_INT i;
	double mad;

	if ( N <= 0 ) {
		return 0.0 / 0.0; // NaN
	}

	// 1. Calculate the median of the input array X
	median = API_SUFFIX(stdlib_strided_dmediansorted_ndarray)( N, X, strideX, offsetX );
	if ( isnan(median) ) {
		return 0.0 / 0.0; // NaN
	}

	// 2. Create a temporary array to store the absolute differences
	diffs = (double *)malloc( N * sizeof(double) );
	if ( diffs == NULL ) {
		// Handle memory allocation failure
		return 0.0 / 0.0; // NaN
	}

	// 3. Populate the temporary array with the absolute differences
	for ( i = 0; i < N; i++ ) {
		diffs[ i ] = fabs( X[ offsetX + (i * strideX) ] - median );
	}

	// 4. Sort this temporary array
	qsort( diffs, N, sizeof(double), compare_doubles );

	// 5. Calculate the median of the sorted temporary array (which are the absolute differences)
	// Here, strideX for diffs is 1 and offsetX is 0 as it's a contiguous array
	mad = API_SUFFIX(stdlib_strided_dmediansorted_ndarray)( N, diffs, 1, 0 );

	// Free the allocated memory
	free( diffs );

	return mad;
}
